// One generator per process.
const EPOCH = 1577836800000n;           // 2020-01-01
let lastMs = -1n, seq = 0n;

function nextId(workerId /* 0..1023 */) {
  let now = BigInt(Date.now());
  if (now < lastMs) throw new Error("clock moved backwards");   // see below
  if (now === lastMs) {
    seq = (seq + 1n) & 4095n;
    if (seq === 0n) while ((now = BigInt(Date.now())) <= lastMs) {}  // wait for next ms
  } else seq = 0n;
  lastMs = now;
  return ((now - EPOCH) << 22n) | (BigInt(workerId) << 12n) | seq;
}
